_cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>
#include <vector>
constexpr int LN_THREADS = 128;
constexpr int LN_CHUNKS = 128;
__global__ void layer_norm_partial_kernel(
    const float* __restrict__ input,
    double* __restrict__ partial_sum,
    double* __restrict__ partial_sq_sum,
    int64_t rows,
    int64_t normalized_size,
    int64_t chunks,
    int64_t chunk_size) {
    const int64_t block_id = static_cast<int64_t>(blockIdx.x);
    const int64_t row = block_id / chunks;
    const int64_t chunk = block_id - row * chunks;
    if (row >= rows) {
        return;
    }
    const int64_t begin = chunk * chunk_size;
    const int64_t end = min(begin + chunk_size, normalized_size);
    const int64_t base = row * normalized_size;
    __shared__ double sums[LN_THREADS / 32];
    __shared__ double sq_sums[LN_THREADS / 32];
    double sum = 0.0;
    double sq_sum = 0.0;
    int64_t i = begin;
    const unsigned long long input_addr =
        reinterpret_cast<unsigned long long>(input + base + begin);
    const int64_t vec_end = begin + ((end - begin) / 4) * 4;
    if ((input_addr & 15ULL) == 0ULL) {
        for (; i < vec_end; i += 4 * blockDim.x) {
            const int64_t idx = i + 4 * threadIdx.x;
            if (idx < vec_end) {
                const float4 value4 =
                    *reinterpret_cast<const float4*>(input + base + idx);
                sum += static_cast<double>(value4.x) +
                       static_cast<double>(value4.y) +
                       static_cast<double>(value4.z) +
                       static_cast<double>(value4.w);
                sq_sum += static_cast<double>(value4.x) * value4.x +
                          static_cast<double>(value4.y) * value4.y +
                          static_cast<double>(value4.z) * value4.z +
                          static_cast<double>(value4.w) * value4.w;
            }
        }
        i = vec_end + threadIdx.x;
    }
    for (; i < end; i += blockDim.x) {
        const double value = static_cast<double>(input[base + i]);
        sum += value;
        sq_sum += value * value;
    }
    const unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sq_sum += __shfl_down_sync(mask, sq_sum, offset);
    }
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) {
        sums[warp] = sum;
        sq_sums[warp] = sq_sum;
    }
    __syncthreads();
    if (warp == 0) {
        sum = lane < (LN_THREADS / 32) ? sums[lane] : 0.0;
        sq_sum = lane < (LN_THREADS / 32) ? sq_sums[lane] : 0.0;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(mask, sum, offset);
            sq_sum += __shfl_down_sync(mask, sq_sum, offset);
        }
        if (lane == 0) {
            const int64_t partial_index = row * chunks + chunk;
            partial_sum[partial_index] = sum;
            partial_sq_sum[partial_index] = sq_sum;
        }
    }
}
__global__ void layer_norm_stats_kernel(
    const double* __restrict__ partial_sum,
    const double* __restrict__ partial_sq_sum,
    double* __restrict__ means,
    double* __restrict__ inv_stds,
    int64_t rows,
    int64_t normalized_size,
    int64_t chunks,
    double eps) {
    const int64_t stride =
        static_cast<int64_t>(gridDim.x) * static_cast<int64_t>(blockDim.x);
    for (int64_t row =
             static_cast<int64_t>(blockIdx.x) * static_cast<int64_t>(blockDim.x) +
             static_cast<int64_t>(threadIdx.x);
         row < rows;
         row += stride) {
        double sum = 0.0;
        double sq_sum = 0.0;
        const int64_t offset = row * chunks;
        for (int64_t chunk = 0; chunk < chunks; ++chunk) {
            sum += partial_sum[offset + chunk];
            sq_sum += partial_sq_sum[offset + chunk];
        }
        const double mean = sum / static_cast<double>(normalized_size);
        double variance =
            sq_sum / static_cast<double>(normalized_size) - mean * mean;
        variance = fmax(variance, 0.0);
        means[row] = mean;
        inv_stds[row] = 1.0 / sqrt(variance + eps);
    }
}
__global__ void layer_norm_output_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const double* __restrict__ means,
    const double* __restrict__ inv_stds,
    float* __restrict__ output,
    int64_t rows,
    int64_t normalized_size,
    int64_t chunks,
    int64_t chunk_size) {
    const int64_t block_id = static_cast<int64_t>(blockIdx.x);
    const int64_t row = block_id / chunks;
    const int64_t chunk = block_id - row * chunks;
    if (row >= rows) {
        return;
    }
    const int64_t begin = chunk * chunk_size;
    const int64_t end = min(begin + chunk_size, normalized_size);
    const int64_t base = row * normalized_size;
    const float mean = static_cast<float>(means[row]);
    const float inv_std = static_cast<float>(inv_stds[row]);
    int64_t i = begin + threadIdx.x;
    const int64_t vec_end = begin + ((end - begin) / 4) * 4;
    const unsigned long long input_addr =
        reinterpret_cast<unsigned long long>(input + base + begin);
    const unsigned long long weight_addr =
        reinterpret_cast<unsigned long long>(weight + begin);
    const unsigned long long bias_addr =
        reinterpret_cast<unsigned long long>(bias + begin);
    const unsigned long long output_addr =
        reinterpret_cast<unsigned long long>(output + base + begin);
    if ((input_addr & 15ULL) == 0ULL &&
        (weight_addr & 15ULL) == 0ULL &&
        (bias_addr & 15ULL) == 0ULL &&
        (output_addr & 15ULL) == 0ULL) {
        for (int64_t idx = begin + 4 * threadIdx.x;
             idx < vec_end;
             idx += 4 * blockDim.x) {
            const float4 x4 =
                *reinterpret_cast<const float4*>(input + base + idx);
            const float4 w4 =
                *reinterpret_cast<const float4*>(weight + idx);
            const float4 b4 =
                *reinterpret_cast<const float4*>(bias + idx);
            float4 y4;
            y4.x = (x4.x - mean) * inv_std * w4.x + b4.x;
            y4.y = (x4.y - mean) * inv_std * w4.y + b4.y;
            y4.z = (x4.z - mean) * inv_std * w4.z + b4.z;
            y4.w = (x4.w - mean) * inv_std * w4.w + b4.w;
            *reinterpret_cast<float4*>(output + base + idx) = y4;
        }
        i = vec_end + threadIdx.x;
    }
    for (; i < end; i += blockDim.x) {
        const float normalized = (input[base + i] - mean) * inv_std;
        output[base + i] = normalized * weight[i] + bias[i];
    }
}
torch::Tensor layer_norm_cuda(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const torch::Tensor& bias) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
     TORCH_CHECK(input.device() == weight.device(),
                 "input and weight must be on the same CUDA device");
     TORCH_CHECK(input.device() == bias.device(),
                 "input and bias must be on the same CUDA device");
     TORCH_CHECK(input.dim() >= weight.dim(),
                 "input must have at least as many dimensions as normalized_shape");
     for (int64_t d = 0; d < weight.dim(); ++d) {
         TORCH_CHECK(
             input.size(input.dim() - weight.dim() + d) == weight.size(d),
             "input trailing dimensions must match normalized_shape");
     }
    TORCH_CHECK(weight.numel() == bias.numel(), "weight and bias sizes must match");
    TORCH_CHECK(weight.numel() > 0, "normalized size must be positive");
    TORCH_CHECK(input.numel() % weight.numel() == 0,
                "input size must be divisible by normalized size");
    const auto device = input.device();
    c10::cuda::CUDAGuard device_guard(device);
    auto output = torch::empty_like(input);
    const int64_t normalized_size = weight.numel();
    const int64_t rows = input.numel() / normalized_size;
    const int64_t chunks = std::min<int64_t>(LN_CHUNKS, normalized_size);
    const int64_t chunk_size = (normalized_size + chunks - 1) / chunks;
    const int64_t total_blocks = rows * chunks;
    auto partial_sum = torch::empty(
        {rows, chunks}, input.options().dtype(torch::kFloat64));
    auto partial_sq_sum = torch::empty(
        {rows, chunks}, input.options().dtype(torch::kFloat64));
    auto means = torch::empty(
        {rows}, input.options().dtype(torch::kFloat64));
    auto inv_stds = torch::empty(
        {rows}, input.options().dtype(torch::kFloat64));
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(device.index());
    layer_norm_partial_kernel<<<static_cast<int>(total_blocks), LN_THREADS, 0, stream>>>(
        input.data_ptr<float>(),
        partial_sum.data_ptr<double>(),
        partial_sq_sum.data_ptr<double>(),
        rows,
        normalized_size,
        chunks,
        chunk_size);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    layer_norm_stats_kernel<<<
        static_cast<int>(std::min<int64_t>((rows + 255) / 256, 4096)),
        256,
        0,
        stream>>>
        (partial_sum.data_ptr<double>(),
         partial_sq_sum.data_ptr<double>(),
         means.data_ptr<double>(),
         inv_stds.data_ptr<double>(),
         rows,
         normalized_size,
         chunks,
         1.0e-5);
    layer_norm_output_kernel<<<static_cast<int>(total_blocks), LN_THREADS, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        means.data_ptr<double>(),
        inv_stds.data_ptr<double>(),
        output.data_ptr<float>(),
        rows,
        normalized_size,
        chunks,
        chunk_size);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""


_layer_norm_ext = load_inline(
    name="fused_layer_norm_cuda_ext",
    cpp_sources=_cpp_source,
    cuda_sources=_cuda_source,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_contiguous = x.contiguous()
        return _layer_norm_ext.layer_norm_cuda(
            x_contiguous,
            self.weight,
            self.bias,
        )

